def main():
    canonical = [dict(id=i,title=t,category=c,hours=h,risk=r,owner=o,first_step=s) for i,t,c,h,r,o,s in SHORTLIST]
    pool = [dict(id=f'{li:02d}-{j:02d}',lens=l,title=t,canonical_id=cid,typical_team_probability=p,
                 probability_status='subjective_uncalibrated_generation_prior',elo=None)
            for li,(l,rows) in enumerate(LENSES.items(),1) for j,(cid,t,p) in enumerate(rows,1)]
    out = dict(created_at=DAY,method='separate ten-response distribution per lens, then canonical consolidation',
               limitation='LLM role-play is not expert testimony. Probabilities are not empirical frequencies. Elo is supplied by independent critic tournament.',
               canonical_candidates=canonical,raw_pool=pool)
    (ROOT/'ideas.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    print(f'{len(canonical)} canonical candidates; {len(pool)} raw ideas across {len(LENSES)} lenses; {sum(x["typical_team_probability"]<.1 for x in pool)} tail ideas')

if __name__ == '__main__': main()
